PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,name TEXT NOT NULL,platform_role TEXT NOT NULL DEFAULT 'venue' CHECK(platform_role IN ('venue','admin','brand')),brand_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS venues(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,timezone TEXT NOT NULL,plan TEXT NOT NULL DEFAULT 'free' CHECK(plan IN ('free','paid','premium')),seats INTEGER NOT NULL DEFAULT 5,theme TEXT NOT NULL DEFAULT 'modern-luxury',accent TEXT NOT NULL DEFAULT '#c7aa77',mix TEXT NOT NULL,qr_code TEXT NOT NULL UNIQUE,referral_code TEXT NOT NULL UNIQUE,referred_by TEXT REFERENCES venues(id),stripe_customer TEXT,stripe_subscription TEXT,billing_status TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(venue_id TEXT NOT NULL REFERENCES venues(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','viewer')),PRIMARY KEY(venue_id,user_id));
CREATE TABLE IF NOT EXISTS tvs(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),name TEXT NOT NULL,group_name TEXT NOT NULL DEFAULT '',rotation_seed INTEGER NOT NULL DEFAULT 0,token_hash TEXT UNIQUE NOT NULL,revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0,1)),mix TEXT,theme TEXT,last_seen INTEGER,cache_seconds INTEGER NOT NULL DEFAULT 0,cache_bytes INTEGER NOT NULL DEFAULT 0,playing INTEGER NOT NULL DEFAULT 0,current_title TEXT NOT NULL DEFAULT '',last_ack INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS tv_venue ON tvs(venue_id);
CREATE TABLE IF NOT EXISTS pairings(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,poll_hash TEXT NOT NULL,device_token_hash TEXT NOT NULL,tv_id TEXT REFERENCES tvs(id),expires_at INTEGER NOT NULL,claimed_at INTEGER);
CREATE TABLE IF NOT EXISTS commands(id INTEGER PRIMARY KEY AUTOINCREMENT,tv_id TEXT NOT NULL REFERENCES tvs(id),kind TEXT NOT NULL,payload TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,ack_at INTEGER);
CREATE INDEX IF NOT EXISTS command_queue ON commands(tv_id,id);
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY,title TEXT NOT NULL,worlds TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '[]',duration INTEGER NOT NULL CHECK(duration BETWEEN 1 AND 14400),provider TEXT NOT NULL CHECK(provider IN ('bunny','demo')),asset_id TEXT NOT NULL,resolution INTEGER NOT NULL DEFAULT 720,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')),ready INTEGER NOT NULL DEFAULT 0,clean INTEGER NOT NULL DEFAULT 1,premium_only INTEGER NOT NULL DEFAULT 0,sponsor INTEGER NOT NULL DEFAULT 0,rights_confirmed INTEGER NOT NULL DEFAULT 0,rights_until INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,brand_id TEXT NOT NULL,name TEXT NOT NULL,content_id TEXT NOT NULL REFERENCES content(id),world TEXT NOT NULL,venue_type TEXT NOT NULL DEFAULT '',starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),name TEXT NOT NULL,days TEXT NOT NULL,tv_ids TEXT NOT NULL,start_time TEXT NOT NULL,end_time TEXT NOT NULL,mix TEXT NOT NULL,theme TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS manifests(id TEXT PRIMARY KEY,tv_id TEXT NOT NULL REFERENCES tvs(id),payload TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS qr_links(code TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),tv_id TEXT REFERENCES tvs(id),content_id TEXT REFERENCES content(id),campaign_id TEXT REFERENCES campaigns(id),manifest_id TEXT REFERENCES manifests(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,tv_id TEXT NOT NULL REFERENCES tvs(id),manifest_id TEXT NOT NULL REFERENCES manifests(id),content_id TEXT NOT NULL REFERENCES content(id),campaign_id TEXT REFERENCES campaigns(id),playback_id TEXT NOT NULL,kind TEXT NOT NULL,seconds REAL NOT NULL DEFAULT 0,occurred_at INTEGER NOT NULL,received_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_tv ON events(tv_id,occurred_at);
CREATE TABLE IF NOT EXISTS scans(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),tv_id TEXT REFERENCES tvs(id),content_id TEXT REFERENCES content(id),campaign_id TEXT REFERENCES campaigns(id),manifest_id TEXT REFERENCES manifests(id),created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS scans_venue ON scans(venue_id,created_at);
CREATE TABLE IF NOT EXISTS orders(external_id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id),venue_id TEXT NOT NULL REFERENCES venues(id),net_cents INTEGER NOT NULL,refund_cents INTEGER NOT NULL DEFAULT 0,commission_bps INTEGER NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),order_id TEXT REFERENCES orders(external_id),kind TEXT NOT NULL,amount_cents INTEGER NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),reference TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS immutable_ledger_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'Ledger is append-only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_ledger_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'Ledger is append-only'); END;
CREATE TABLE IF NOT EXISTS hooks(event_id TEXT PRIMARY KEY,kind TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS promotions(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),kind TEXT NOT NULL CHECK(kind IN ('barrel-pick','exclusive-label','event','referral')),title TEXT NOT NULL,description TEXT NOT NULL,starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS contracts(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),years INTEGER NOT NULL CHECK(years IN (5,10)),tvs INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','declined')),signed_ref TEXT NOT NULL DEFAULT '',expires_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS billing_requests(id TEXT PRIMARY KEY,venue_id TEXT NOT NULL REFERENCES venues(id),plan TEXT NOT NULL,seats INTEGER NOT NULL,url TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,actor_id TEXT,venue_id TEXT,action TEXT NOT NULL,detail TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INTEGER NOT NULL,expires_at INTEGER NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,unixepoch()*1000);
